// Perception / rep-loss / prediction-equation references (Part 6 research pass, 2026-11-23). Each PMID was fetched
// from PubMed (E-utilities) and its DOI resolved in Crossref with a matching title; no retraction notices. Titles,
// authors, journal and year are copied from the PubMed record; summaries are our own words, from the abstract
// (or the free full text where the finding says so). See SCIENTIFIC_METHOD.md.
import type { Reference } from './references';
import { L, byLang } from '../../i18n/core';

export const PERCEPTION_REFERENCES: Reference[] = byLang(() => [
  {"id": "zourdos2021_rir_accuracy_squat", "title": "Proximity to Failure and Total Repetitions Performed in a Set Influences Accuracy of Intraset Repetitions in Reserve-Based Rating of Perceived Exertion.", "authors": "Zourdos MC et al.", "year": 2021, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000002995", "pmid": "30747900", "url": "https://pubmed.ncbi.nlm.nih.gov/30747900/", "design": "acute_other", "outcome": "other", "population": "25 resistance-trained men (about 4.7 years of training); one back-squat set to failure at 70% 1RM (16 ± 4 reps), calling out when they believed they were at 5, 3 and 1 RIR", "finding": L("The gap between called and actual reps left shrank as failure approached: 5.15 ± 2.92 reps at a called 5 RIR, 3.65 ± 2.46 at 3 RIR and 2.05 ± 1.73 at 1 RIR. Longer sets meant larger errors at the 5-RIR (r = 0.65) and 3-RIR (r = 0.56) calls but not at the 1-RIR call (r = 0.01). Training age did not predict accuracy.", "Разрыв между названным и фактическим числом оставшихся повторений сокращался по мере приближения к отказу: 5,15 ± 2,92 повторения при названных 5 RIR, 3,65 ± 2,46 при 3 RIR и 2,05 ± 1,73 при 1 RIR. Более длинные подходы означали большие ошибки при оценках 5 RIR (r = 0,65) и 3 RIR (r = 0,56), но не при 1 RIR (r = 0,01). Тренировочный стаж точность не предсказывал."), "muscles": ["quads"], "limitations": "One high-rep squat set (about 16 reps) in 25 men, so errors are larger than in typical 6-12 rep sets; the abstract reports the size of the error but does not spell out its direction; acute accuracy only.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "hackett2017_erf_accuracy", "title": "Accuracy in Estimating Repetitions to Failure During Resistance Exercise.", "authors": "Hackett DA et al.", "year": 2017, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000001683", "pmid": "27787474", "url": "https://pubmed.ncbi.nlm.nih.gov/27787474/", "design": "acute_other", "outcome": "other", "population": "81 adults (53 men, 28 women) with a wide range of resistance-training experience; up to 10 sets of 10 reps on chest press (70% 1RM) and leg press (80% 1RM), estimating reps left after each set and then continuing to failure", "finding": L("Estimation error depended on how far from failure the estimate was made: about 1 rep when 0-5 reps were actually left, more than 2 reps when 7-10 were left. Chest press was estimated more accurately than leg press (error of 1 rep or less up to 5 reps from failure on chest press, but only up to 3 reps from failure on leg press). Men were more accurate than women at some distances on leg press only. Training experience did not affect accuracy.", "Ошибка оценки зависела от того, насколько далеко от отказа делалась оценка: около 1 повторения, когда на самом деле оставалось 0–5 повторений, и больше 2 повторений, когда оставалось 7–10. Жим от груди оценивали точнее, чем жим ногами (ошибка 1 повторение и меньше — до 5 повторений от отказа в жиме от груди, но только до 3 повторений от отказа в жиме ногами). Мужчины были точнее женщин на некоторых расстояниях от отказа только в жиме ногами. Опыт тренировок на точность не влиял."), "muscles": [], "limitations": "Two exercises at fixed loads; estimates given after a fixed 10 reps rather than at a chosen RIR; the abstract does not state the direction of the error; acute accuracy only.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "steele2017_predict_reps_failure", "title": "Ability to predict repetitions to momentary failure is not perfectly accurate, though improves with resistance training experience.", "authors": "Steele J et al.", "year": 2017, "journal": "PeerJ", "doi": "10.7717/peerj.4105", "pmid": "29204323", "url": "https://pubmed.ncbi.nlm.nih.gov/29204323/", "design": "cross_sectional", "outcome": "other", "population": "141 gym members in five experience groups (from first sessions to expert); single sets to momentary failure on six exercises in one full-body session, with reps-to-failure predicted before each set", "finding": L("People predicted fewer reps than they then achieved. Standard error of measurement for the whole sample ranged from 2.64 reps (elbow flexion) to 3.38 reps (leg press). In the free full text, mean predicted vs actual reps were 12.4 vs 14.2 on chest press, 11.5 vs 12.5 on elbow flexion, 12.5 vs 13.8 on pulldown and 12.5 vs 16.4 on leg press; the gap narrowed with experience (most experienced group: 10.5 vs 10.9 on chest press, 10.7 vs 12.1 on leg press).", "Люди прогнозировали меньше повторений, чем затем выполняли. Стандартная ошибка измерения для всей выборки составляла от 2,64 повторения (сгибание локтя) до 3,38 повторения (жим ногами). В открытом полном тексте средние прогнозируемые и фактические повторения: 12,4 против 14,2 в жиме от груди, 11,5 против 12,5 в сгибании локтя, 12,5 против 13,8 в тяге сверху и 12,5 против 16,4 в жиме ногами; с опытом разрыв сокращался (самая опытная группа: 10,5 против 10,9 в жиме от груди, 10,7 против 12,1 в жиме ногами)."), "muscles": [], "limitations": "Predictions were made before the set, not during it, so errors are larger than for intra-set RIR calls; sets of 10+ reps; unequal experience groups; the experience trend is descriptive (no formal test in the abstract).", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "refalo2024_rir_accuracy_bench", "title": "Accuracy of Intraset Repetitions-in-Reserve Predictions During the Bench Press Exercise in Resistance-Trained Male and Female Subjects.", "authors": "Refalo MC et al.", "year": 2024, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000004653", "pmid": "37967832", "url": "https://pubmed.ncbi.nlm.nih.gov/37967832/", "design": "acute_other", "outcome": "other", "population": "24 resistance-trained adults (12 men, 12 women); barbell bench press at 75% 1RM, two sets to momentary failure in each of two sessions, calling out perceived 1 RIR or 3 RIR", "finding": L("Across all sets the mean signed error was -0.17 ± 1.00 reps and the mean absolute error 0.65 ± 0.78 reps, which the authors describe as a minor tendency to underpredict. Accuracy was statistically equivalent (within ±1 rep) for 1-RIR vs 3-RIR calls, set 1 vs set 2 and session 1 vs session 2, and was unrelated to sex, years of training or relative bench-press strength.", "По всем подходам средняя ошибка со знаком составила −0,17 ± 1,00 повторения, а средняя абсолютная ошибка — 0,65 ± 0,78 повторения, что авторы описывают как небольшую склонность к недооценке. Точность была статистически эквивалентной (в пределах ±1 повторения) для оценок 1 RIR и 3 RIR, 1-го и 2-го подходов, 1-й и 2-й тренировок и не была связана с полом, стажем тренировок или относительной силой в жиме лёжа."), "muscles": ["chest"], "limitations": "One exercise, one load and only calls of 1 and 3 RIR, in trained lifters under supervision; says nothing about calls of 4+ RIR, lighter loads or lower-body lifts. Print year 2024 (online 2023).", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "remmert2023_rir_accuracy_single_joint", "title": "Accuracy of Predicted Intraset Repetitions in Reserve (RIR) in Single- and Multi-Joint Resistance Exercises Among Trained and Untrained Men and Women.", "authors": "Remmert JF et al.", "year": 2023, "journal": "Percept Mot Skills", "doi": "10.1177/00315125231169868", "pmid": "37036795", "url": "https://pubmed.ncbi.nlm.nih.gov/37036795/", "design": "acute_other", "outcome": "other", "population": "58 trained and untrained adults (27 men with a mean of 66 months of training, 31 women with a mean of 22 months); 4 sets to momentary failure at 72.5% of estimated 1RM on biceps curl, triceps pushdown and seated row machines, calling 5 RIR and then RIR on every rep", "finding": L("RIR calls were more accurate the closer the set was to failure and in later sets (both p < 0.01). The exercise (curl, pushdown or row) made no difference (p = 0.688), and neither sex, training experience nor prior experience with RIR ratings affected the error.", "Оценки RIR были тем точнее, чем ближе подход был к отказу, и точнее в более поздних подходах (в обоих случаях p < 0,01). Упражнение (сгибания, разгибания на блоке или тяга) значения не имело (p = 0,688), и ни пол, ни опыт тренировок, ни прежний опыт оценок RIR на ошибку не влияли."), "muscles": ["biceps", "triceps"], "limitations": "The abstract gives no error sizes in reps; single session; 1RM estimated from a 5RM test; young adults; machine exercises only.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "grgic2022_failure_meta", "title": "Effects of resistance training performed to repetition failure or non-failure on muscular strength and hypertrophy: A systematic review and meta-analysis.", "authors": "Grgic J et al.", "year": 2022, "journal": "J Sport Health Sci", "doi": "10.1016/j.jshs.2021.01.007", "pmid": "33497853", "url": "https://pubmed.ncbi.nlm.nih.gov/33497853/", "design": "meta_analysis", "outcome": "mixed", "population": "15 studies in young adults comparing sets taken to failure with sets stopped short; subgroups by training status, volume equating, body region, exercise type and study design", "finding": L("No significant difference between failure and non-failure training for strength (ES -0.09, 95% CI -0.22 to 0.05) or hypertrophy (ES 0.22, 95% CI -0.11 to 0.55). Where volume was not equated, non-failure was better for strength (ES -0.32). In resistance-trained participants failure had a small significant hypertrophy advantage (ES 0.15, 95% CI 0.03 to 0.26). The authors conclude that failure is not required for growth but is not detrimental either.", "Значимой разницы между тренировкой до отказа и без отказа нет ни для силы (размер эффекта −0,09, 95% ДИ от −0,22 до 0,05), ни для гипертрофии (размер эффекта 0,22, 95% ДИ от −0,11 до 0,55). Там, где объём не был уравнен, работа без отказа была лучше для силы (размер эффекта −0,32). У участников с опытом силовых тренировок отказ давал небольшое значимое преимущество в гипертрофии (размер эффекта 0,15, 95% ДИ от 0,03 до 0,26). Авторы заключают, что отказ не обязателен для роста, но и не вреден."), "muscles": [], "limitations": "Only young adults; wide interval for the pooled hypertrophy effect; the distance from failure in the non-failure groups varied and was often not quantified; subgroup results are exploratory. Print year 2022 (online 2021).", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "vieira2021_failure_meta", "title": "Effects of Resistance Training Performed to Failure or Not to Failure on Muscle Strength, Hypertrophy, and Power Output: A Systematic Review With Meta-Analysis.", "authors": "Vieira AF et al.", "year": 2021, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000003936", "pmid": "33555822", "url": "https://pubmed.ncbi.nlm.nih.gov/33555822/", "design": "meta_analysis", "outcome": "mixed", "population": "13 randomised and non-randomised studies in adults, interventions of at least 6 weeks, training to failure vs not to failure", "finding": L("Across all studies hypertrophy favoured training to failure (SMD 0.75, p = 0.005), but the difference disappeared when volume was equated between groups. Maximal strength did not differ overall (SMD -0.08) and favoured not-to-failure when volumes were not equated (SMD -0.34); power also favoured not-to-failure with non-equated volumes (SMD -0.61).", "По всем исследованиям гипертрофия была больше при тренировке до отказа (SMD 0,75, p = 0,005), но разница исчезала, когда объём между группами был уравнен. Максимальная сила в целом не различалась (SMD −0,08) и была больше без отказа при неуравненных объёмах (SMD −0,34); мощность при неуравненных объёмах тоже была больше без отказа (SMD −0,61)."), "muscles": [], "limitations": "Mixes randomised and non-randomised trials; the overall hypertrophy effect is confounded by unequal volume; non-failure protocols differ widely in how far from failure they stop.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "wu2026_nonfailure_meta", "title": "Effects of resistance training performed to repetition non-failure on exercise performance in healthy adults: a systematic review and meta-analysis.", "authors": "Wu S et al.", "year": 2026, "journal": "BMC Sports Sci Med Rehabil", "doi": "10.1186/s13102-026-01861-z", "pmid": "42410632", "url": "https://pubmed.ncbi.nlm.nih.gov/42410632/", "design": "meta_analysis", "outcome": "mixed", "population": "20 randomised controlled trials with 556 healthy adults comparing non-failure with failure training", "finding": L("Stopping short of failure gave slightly better dynamic strength gains (SMD 0.24, 95% CI 0.06 to 0.42). Hypertrophy, isometric strength, muscular endurance and power did not differ significantly between failure and non-failure training. Participant characteristics, volume, training method and duration moderated the effects.", "Остановка до отказа дала немного лучший прирост динамической силы (SMD 0,24, 95% ДИ от 0,06 до 0,42). Гипертрофия, изометрическая сила, мышечная выносливость и мощность значимо не различались между тренировкой до отказа и без него. Эффекты зависели от характеристик участников, объёма, метода и длительности тренировок."), "muscles": [], "limitations": "The abstract gives no effect size for hypertrophy; the actual RIR of non-failure groups varies between trials; subgroup moderators are exploratory.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "vasconcelos2026_elbow_flexor_failure", "title": "Elbow Flexor Adaptations to Failure Versus Repetitions-in-Reserve Training: A Unilateral Within-Participant Study in Resistance-Trained Adults.", "authors": "Vasconcelos T et al.", "year": 2026, "journal": "Muscles", "doi": "10.3390/muscles5030061", "pmid": "42784046", "url": "https://pubmed.ncbi.nlm.nih.gov/42784046/", "design": "longitudinal_trial", "outcome": "mixed", "population": "19 resistance-trained adults; one arm trained to momentary failure and the other with 1-3 RIR; unilateral preacher curl at 70-80% 1RM, twice weekly for 8 weeks", "finding": L("Elbow-flexor thickness and 1RM increased in both arms. The between-condition difference in thickness was 0.032 cm (95% HDI -0.044 to 0.113) and in 1RM 0.59 kg (interval spanning zero), so stopping 1-3 reps short produced growth similar to training to failure. Men and women showed the same pattern.", "Толщина сгибателей локтя и 1RM выросли на обеих руках. Разница между условиями составила 0,032 см по толщине (95% HDI от −0,044 до 0,113) и 0,59 кг по 1RM (интервал включает ноль), то есть остановка за 1–3 повторения до отказа дала рост, схожий с тренировкой до отказа. У мужчин и женщин картина была одинаковой."), "muscles": ["biceps"], "limitations": "n = 19; one exercise; 8 weeks; ultrasound thickness; RIR self-perceived; the abstract does not say how arms were allocated to conditions.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "bazvalle2021_sets_quantification", "title": "Total Number of Sets as a Training Volume Quantification Method for Muscle Hypertrophy: A Systematic Review.", "authors": "Baz-Valle E et al.", "year": 2021, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000002776", "pmid": "30063555", "url": "https://pubmed.ncbi.nlm.nih.gov/30063555/", "design": "systematic_review", "outcome": "long_term_hypertrophy", "population": "14 randomised trials of at least 6 weeks in adults aged 18-35 with at least 1 year of resistance training that compared number of sets, repetition range or frequency and measured muscle size", "finding": L("The review concludes that the total number of sets taken to failure, or close to it, is an adequate way to quantify hypertrophy training volume when reps per set lie between about 6 and 20+, provided the other variables are held constant. It does not identify a particular optimal number of sets.", "Обзор заключает, что общее число подходов, доведённых до отказа или близко к нему, — адекватный способ количественно оценивать объём тренировки на гипертрофию, когда повторений в подходе примерно от 6 до 20+, при условии что остальные переменные постоянны. Конкретного оптимального числа подходов он не называет."), "muscles": [], "limitations": "Qualitative synthesis without meta-analysis; search closed May 2018; 'near failure' is given no numeric RIR boundary in the abstract; the abstract does not mention warm-up sets.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "dankel2017_training_to_fatigue", "title": "Training to Fatigue: The Answer for Standardization When Assessing Muscle Hypertrophy?", "authors": "Dankel SJ et al.", "year": 2017, "journal": "Sports Med", "doi": "10.1007/s40279-016-0633-7", "pmid": "27677915", "url": "https://pubmed.ncbi.nlm.nih.gov/27677915/", "design": "narrative_review", "outcome": "other", "population": "Opinion article on how resistance-training studies of hypertrophy prescribe and report the training stimulus", "finding": L("Argues that a fixed number of reps at a relative load does not give every person the same stimulus, and that volume reported as load × reps cannot be replicated across people. Because the fatigue reached in a set is treated as the indicator of its hypertrophic potential, the authors propose standardising hypertrophy studies by taking every set to volitional fatigue.", "Утверждается, что фиксированное число повторений с относительным весом не даёт каждому человеку одинаковый стимул и что объём, записанный как вес × повторения, нельзя воспроизвести у разных людей. Поскольку утомление, достигнутое в подходе, рассматривается как показатель его гипертрофического потенциала, авторы предлагают стандартизировать исследования гипертрофии, доводя каждый подход до произвольного утомления."), "muscles": [], "limitations": "Opinion piece, not a systematic review; argues for a reporting standard rather than testing one; the abstract does not discuss sets stopped a few reps short of failure or warm-up sets. Print year 2017 (online 2016).", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "senna2019_bench_fly_order", "title": "Multi- To Single-Joint or the Reverse Exercise Order Does Not Affect Pectoralis Major Workout Performance.", "authors": "Senna GW et al.", "year": 2019, "journal": "J Hum Kinet", "doi": "10.2478/hukin-2018-0059", "pmid": "30988856", "url": "https://pubmed.ncbi.nlm.nih.gov/30988856/", "design": "acute_other", "outcome": "other", "population": "14 resistance-trained men; 5 sets to failure of bench press and of machine chest fly with 10RM loads and 2 min rest, performed in both orders (crossover)", "finding": L("Total session reps did not differ between orders (62.2 vs 55.4, p = 0.14), but whichever exercise came second lost reps: bench press 34.4 reps over 5 sets when done first vs 25.9 after the fly (about 25% fewer), machine fly 33.5 when first vs 27.9 after bench press (about 17% fewer). In the free full text the loss was concentrated in the first sets of the second exercise and had disappeared by the fifth set; RPE for the fly was higher in its first three sets when it came second.", "Общее число повторений за тренировку между порядками не различалось (62,2 против 55,4, p = 0,14), но упражнение, шедшее вторым, теряло повторения: жим лёжа — 34,4 повторения за 5 подходов первым против 25,9 после сведений (примерно на 25% меньше), сведения в тренажёре — 33,5 первыми против 27,9 после жима (примерно на 17% меньше). В открытом полном тексте потеря была сосредоточена в первых подходах второго упражнения и исчезала к пятому подходу; воспринимаемое усилие (RPE) в сведениях было выше в первых трёх подходах, когда они шли вторыми."), "muscles": ["chest"], "limitations": "Small acute crossover; each exercise followed five sets to failure of the other, which is more prior work than most sessions; fixed 10RM load, so the result is reps lost, not the load reduction needed; per-set rep counts are shown only in a figure.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "vilacaalves2014_biceps_preexhaustion", "title": "Effects of pre-exhausting the biceps brachii muscle on the performance of the front lat pull-down exercise using different handgrip positions.", "authors": "Vilaça-Alves J et al.", "year": 2014, "journal": "J Hum Kinet", "doi": "10.2478/hukin-2014-0070", "pmid": "25414749", "url": "https://pubmed.ncbi.nlm.nih.gov/25414749/", "design": "acute_other", "outcome": "other", "population": "19 recreationally trained adults (8 men, 11 women); lat pulldown to failure at 70% 1RM with a wide and a narrow grip, with and without prior biceps work (3 sets of 10 barbell curls at 70% 1RM, 90 s rest)", "finding": L("Fatiguing the biceps first reduced pulldown reps and raised RPE in both sexes. In the free full text, men completed 13.6 vs 10.8 reps with the wide grip and 14.5 vs 9.4 with the narrow grip (without vs with curls first); women 12.2 vs 9.9 and 11.4 vs 8.1. That is roughly 20% fewer reps with a wide grip and about 30-35% fewer with a narrow grip.", "Предварительное утомление бицепса снижало число повторений в тяге верхнего блока и повышало RPE у обоих полов. В открытом полном тексте: мужчины выполнили 13,6 против 10,8 повторения широким хватом и 14,5 против 9,4 узким (без сгибаний перед тягой и с ними); женщины — 12,2 против 9,9 и 11,4 против 8,1. Это примерно на 20% меньше повторений широким хватом и примерно на 30–35% меньше узким."), "muscles": ["lats", "biceps"], "limitations": "One pulldown set per condition; the prior work was three sets for a synergist rather than a single pre-exhaustion set; conditions tested on different days; metronome-paced reps; small sample.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "augustsson2003_preexhaustion_legpress", "title": "Effect of pre-exhaustion exercise on lower-extremity muscle activation during a leg press exercise.", "authors": "Augustsson J et al.", "year": 2003, "journal": "J Strength Cond Res", "doi": "10.1519/1533-4287(2003)017<0411:eopeol>2.0.co;2", "pmid": "12741886", "url": "https://pubmed.ncbi.nlm.nih.gov/12741886/", "design": "acute_emg", "outcome": "emg_activation", "population": "17 healthy men; one set of leg press at a 10RM load with and without an immediately preceding set of knee extension at 10RM", "finding": L("After the knee-extension set the men completed significantly fewer leg-press reps (p < 0.001), and quadriceps EMG (rectus femoris, vastus lateralis) during the leg press was lower rather than higher; gluteus maximus EMG did not change. The abstract does not give the rep counts.", "После подхода разгибаний ног мужчины выполнили значимо меньше повторений в жиме ногами (p < 0,001), а ЭМГ квадрицепса (прямая мышца бедра, латеральная широкая) в жиме ногами была ниже, а не выше; ЭМГ большой ягодичной не изменилась. Числа повторений в аннотации не приведены."), "muscles": ["quads", "glutes"], "limitations": "Primary outcome was EMG, with reps as a secondary measure; single set; the two exercises were done back to back; rep numbers are not in the abstract (full text not accessed).", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "gentil2007_pecdeck_chestpress_order", "title": "Effects of exercise order on upper-body muscle activation and exercise performance.", "authors": "Gentil P et al.", "year": 2007, "journal": "J Strength Cond Res", "doi": "10.1519/R-21216.1", "pmid": "18076251", "url": "https://pubmed.ncbi.nlm.nih.gov/18076251/", "design": "acute_emg", "outcome": "emg_activation", "population": "13 men with recreational weight-training experience; one set each of pec deck and chest press with 10RM loads in both orders (pre-exhaustion vs priority), balanced crossover", "finding": L("Total repetitions and total work over the two exercises did not differ between orders. Doing the pec deck first did not raise pectoral or anterior-deltoid EMG in the chest press; only triceps activity increased. The authors conclude that the exercise whose performance matters most should be placed first.", "Общее число повторений и общая работа за два упражнения между порядками не различались. Пек-дек перед жимом не повысил ЭМГ грудных и передней дельты в жиме от груди; выросла только активность трицепса. Авторы заключают, что первым следует ставить упражнение, результат в котором важнее всего."), "muscles": ["chest", "triceps"], "limitations": "One set per exercise; the abstract reports totals over both exercises, not the reps of each exercise by position; EMG is the main outcome; small sample.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "miranda2010_order_rest_interaction", "title": "Exercise order interacts with rest interval during upper-body resistance exercise.", "authors": "Miranda H et al.", "year": 2010, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0b013e3181d8ea61", "pmid": "20508461", "url": "https://pubmed.ncbi.nlm.nih.gov/20508461/", "design": "acute_other", "outcome": "other", "population": "16 recreationally trained men; 3 sets with 8RM loads on six back and biceps exercises (two pulldowns, two rows, two curls) in two opposite orders, each with 1-minute and with 3-minute rests", "finding": L("Exercises for similar muscle groups produced fewer reps when placed at the end of the session than at the start, and the loss was larger with 1-minute than with 3-minute rests. For the exercises that swapped between first and last position (wide-grip pulldown, machine curl) order mattered more than rest length; for the exercises in the middle of the sequence rest length mattered more than order.", "Упражнения на схожие мышечные группы давали меньше повторений в конце тренировки, чем в начале, и потеря была больше при отдыхе 1 минута, чем при 3 минутах. Для упражнений, менявшихся местами между первой и последней позицией (тяга верхнего блока широким хватом, сгибания в тренажёре), порядок был важнее длительности отдыха; для упражнений в середине последовательности длительность отдыха была важнее порядка."), "muscles": ["lats", "upper_back", "biceps"], "limitations": "The abstract gives rankings of conditions, not rep counts; upper-body pulling exercises only; small sample.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "nuzzo2024_reps_percent_1rm", "title": "Maximal Number of Repetitions at Percentages of the One Repetition Maximum: A Meta-Regression and Moderator Analysis of Sex, Age, Training Status, and Exercise.", "authors": "Nuzzo JL et al.", "year": 2024, "journal": "Sports Med", "doi": "10.1007/s40279-023-01937-7", "pmid": "37792272", "url": "https://pubmed.ncbi.nlm.nih.gov/37792272/", "design": "meta_analysis", "outcome": "other", "population": "952 repetitions-to-failure tests from 269 studies (7289 people in 452 groups; 66% male, 60% resistance-trained); bench press 42% and leg press 14% of the tests", "finding": L("Mean reps to failure and their between-person spread both fall as %1RM rises. In the free full text the general estimates are about 5 reps at 90% and 15 at 70% 1RM; bench press about 4, 9 and 14 reps at 90, 80 and 70%; leg press about 9, 13 and 19. Between-person SD is about 2.5 reps at 80% 1RM but 4.4 reps at 60%, so reps predict relative load much less precisely with light loads. Sex, age and training status changed little; the exercise mattered (more reps on leg press than bench press).", "И среднее число повторений до отказа, и его разброс между людьми снижаются с ростом %1RM. В открытом полном тексте общие оценки — около 5 повторений при 90% и 15 при 70% 1RM; жим лёжа — около 4, 9 и 14 повторений при 90, 80 и 70%; жим ногами — около 9, 13 и 19. Стандартное отклонение между людьми — около 2,5 повторения при 80% 1RM, но 4,4 при 60%, поэтому с лёгкими весами повторения предсказывают относительный вес намного менее точно. Пол, возраст и тренированность меняли мало; упражнение имело значение (в жиме ногами повторений больше, чем в жиме лёжа)."), "muscles": [], "limitations": "Literature search described by the authors as thorough but not systematic; group-level data; only bench press and leg press have their own tables; it describes the reps-load relationship and does not itself test 1RM prediction equations. Print year 2024 (online 2023).", "confidence": "high", "verifiedOn": "2026-11-23"},
  {"id": "reynolds2006_multiple_rm_prediction", "title": "Prediction of one repetition maximum strength from multiple repetition maximum testing and anthropometry.", "authors": "Reynolds JM et al.", "year": 2006, "journal": "J Strength Cond Res", "doi": "10.1519/R-15304.1", "pmid": "16937972", "url": "https://pubmed.ncbi.nlm.nih.gov/16937972/", "design": "cross_sectional", "outcome": "strength", "population": "70 adults (34 men, 36 women, aged 18-69); 1RM, 5RM, 10RM and 20RM tests on barbell bench press and plate-loaded leg press", "finding": L("Load fell non-linearly as the rep target rose. 1RM was predicted best from the 5RM and progressively worse from more reps: R² for 5, 10 and 20RM was 0.993, 0.976 and 0.955 on bench press and 0.974, 0.933 and 0.915 on leg press. The standard error from the 5RM equation was about 3 kg for bench press and 16 kg for leg press. The authors advise using no more than 10 reps in linear 1RM equations.", "Вес снижался нелинейно с ростом целевого числа повторений. 1RM лучше всего предсказывался по весу на 5 повторений и всё хуже — по большему числу повторений: R² для 5, 10 и 20 повторений составил 0,993, 0,976 и 0,955 в жиме лёжа и 0,974, 0,933 и 0,915 в жиме ногами. Стандартная ошибка уравнения по 5 повторениям — около 3 кг для жима лёжа и 16 кг для жима ногами. Авторы советуют использовать в линейных уравнениях 1RM не больше 10 повторений."), "muscles": [], "limitations": "Develops its own regression equations rather than testing Epley; two exercises; the abstract describes no separate validation sample; errors given in kg, not as a percentage.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "mayhew2008_rtf_equations_women", "title": "Accuracy of prediction equations for determining one repetition maximum bench press in women before and after resistance training.", "authors": "Mayhew JL et al.", "year": 2008, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0b013e31817b02ad", "pmid": "18714230", "url": "https://pubmed.ncbi.nlm.nih.gov/18714230/", "design": "longitudinal_trial", "outcome": "strength", "population": "103 young women measured for bench press 1RM and reps to fatigue at an assigned load between 60% and 90% 1RM, before and after 12 weeks of resistance training", "finding": L("Published reps-to-fatigue equations predicted bench press 1RM more accurately when fewer than 10 reps had been performed, both before and after training. 1RM rose 28% while reps at the same %1RM changed little on average (0.6 ± 6.1) but very differently between individuals, so the reps-load relationship of a given person can shift with training.", "Опубликованные уравнения «повторения до утомления» точнее предсказывали 1RM в жиме лёжа, когда было выполнено меньше 10 повторений, — и до, и после тренировочного периода. 1RM вырос на 28%, а число повторений при том же %1RM в среднем изменилось мало (0,6 ± 6,1), но очень по-разному у разных людей, поэтому соотношение повторений и веса у конкретного человека может сдвигаться с тренировками."), "muscles": [], "limitations": "Young women from a wellness course, bench press only; the abstract does not name the equations or give error sizes; reps ranged widely because the %1RM was assigned at random.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "roberts2025_rtf_equations_crossvalidation", "title": "Cross-Validation of Equations for Estimating 1 Repetition Maximum From Repetitions to Failure for the Bench Press and Leg Extension.", "authors": "Roberts TD et al.", "year": 2025, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000004987", "pmid": "39495260", "url": "https://pubmed.ncbi.nlm.nih.gov/39495260/", "design": "cross_sectional", "outcome": "strength", "population": "43 recreationally active young men; 1RM and reps to failure at 80% 1RM on leg extension (bench press in 39 of them); 18 published reps-to-failure equations cross-validated", "finding": L("The most accurate published equations were corrected by subtracting their constant (systematic) error for each movement and then cross-validated again. The authors recommend separate bench-press and leg-extension versions of the corrected equation (different constants), to be used only with loads that give 4-10 reps to failure.", "Наиболее точные опубликованные уравнения скорректировали, вычтя их постоянную (систематическую) ошибку для каждого движения, и затем снова перекрёстно проверили. Авторы рекомендуют отдельные версии скорректированного уравнения для жима лёжа и для разгибаний ног (разные константы) и только для весов, дающих 4–10 повторений до отказа."), "muscles": [], "limitations": "Only 80% 1RM was tested, so the 4-10 rep limit is a recommendation rather than a tested boundary; young men only; the abstract lists neither the individual equations' errors nor a clearly formatted formula (read the full text before coding it). Print year 2025 (online 2024).", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "nickerson2020_rtf_equations_epley", "title": "Evaluation of Load-Velocity Relationships and Repetitions-to-Failure Equations in the Presence of Male and Female Spotters.", "authors": "Nickerson BS et al.", "year": 2020, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000003731", "pmid": "32740290", "url": "https://pubmed.ncbi.nlm.nih.gov/32740290/", "design": "cross_sectional", "outcome": "strength", "population": "20 resistance-trained adults (10 men, 10 women); bench press 1RM measured, then reps to failure at 70% 1RM; 1RM predicted with the Epley, Mayhew and Wathen equations and from individual load-velocity profiles", "finding": L("At 70% 1RM the Epley estimate differed less from the measured 1RM than the Mayhew and Wathen estimates and had the lowest standard error of estimate of all methods; the load-velocity estimate had the largest. For women, the Mayhew and Wathen estimates shifted with the sex of the spotter. The authors recommend Epley over the other methods for loads up to 70% 1RM.", "При 70% 1RM оценка по Эпли меньше отличалась от измеренного 1RM, чем оценки по Мэйхью и Уотену, и имела наименьшую стандартную ошибку оценки среди всех методов; у оценки по профилю «вес — скорость» она была наибольшей. У женщин оценки по Мэйхью и Уотену смещались в зависимости от пола страхующего. Авторы рекомендуют формулу Эпли перед другими методами для весов до 70% 1RM."), "muscles": ["chest"], "limitations": "n = 20; bench press only; a single load (70% 1RM); the abstract gives neither the reps achieved nor the error in kg, so it does not show how accuracy changes with rep count.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "lisboa2024_specific_warmup_older_women", "title": "Effects of static stretching and specific warm-up on the repetition performance in upper- and lower-limb exercises in resistance-trained older women.", "authors": "Lisboa F et al.", "year": 2024, "journal": "Aging Clin Exp Res", "doi": "10.1007/s40520-024-02880-x", "pmid": "39725788", "url": "https://pubmed.ncbi.nlm.nih.gov/39725788/", "design": "acute_other", "outcome": "other", "population": "57 resistance-trained women aged 60+; crossover of a specific warm-up (one 45-second set at about 30-50% of the working load), static stretching or no preparation before leg extension, seated leg curl, triceps pushdown and preacher curl (2 sets to failure each)", "finding": L("A specific warm-up set did not increase reps in any exercise. Total reps over two sets, no preparation vs warm-up (free full text): leg extension 25.7 vs 25.9, seated leg curl 29.3 vs 28.1, triceps pushdown 31.0 vs 28.0, preacher curl 28.1 vs 25.6 - no change for the legs and about 9-10% fewer reps on the two arm exercises. Static stretching gave more reps than the other conditions on the two leg exercises.", "Специальный разминочный подход не увеличил число повторений ни в одном упражнении. Общее число повторений за два подхода, без подготовки и с разминкой (открытый полный текст): разгибания ног 25,7 против 25,9, сгибания ног сидя 29,3 против 28,1, разгибания на блоке 31,0 против 28,0, сгибания на скамье Скотта 28,1 против 25,6 — без изменений для ног и примерно на 9–10% меньше повторений в двух упражнениях на руки. Статическая растяжка дала больше повторений, чем остальные условия, в двух упражнениях на ноги."), "muscles": ["quads", "hamstrings", "triceps", "biceps"], "limitations": "Older trained women on single-joint exercises with 8-12RM loads; the warm-up set lasted 45 s and may itself have been fatiguing; performance only, no injury or long-term outcome.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "amorim2025_warmup_squat_endurance", "title": "Impacts of Traditional Warm-Up and Post-Activation Potentiation on Muscle Endurance During the Back Squat: Response of Blood Lactate, Perceived Effort, and Time Under Tension.", "authors": "Amorim TM et al.", "year": 2025, "journal": "J Funct Morphol Kinesiol", "doi": "10.3390/jfmk10020188", "pmid": "40566438", "url": "https://pubmed.ncbi.nlm.nih.gov/40566438/", "design": "acute_other", "outcome": "other", "population": "12 resistance-trained men (mean age 41); randomised crossover of mobility work only, a traditional warm-up or a post-activation (heavy) warm-up before a back-squat set to failure", "finding": L("Reps to failure were 12.4 after mobility only, 13.6 after the traditional warm-up and 15.6 after the post-activation warm-up; the post-activation protocol beat both others (p < 0.0001). The authors conclude that both warm-ups improved squat endurance relative to mobility alone; the heavy protocol also produced higher lactate and pain ratings.", "Повторений до отказа было 12,4 после одной мобилизации, 13,6 после традиционной разминки и 15,6 после разминки с постактивационным протоколом; постактивационный протокол превзошёл оба других (p < 0,0001). Авторы заключают, что обе разминки улучшили выносливость в приседе по сравнению с одной мобилизацией; тяжёлый протокол также дал более высокие лактат и оценки боли."), "muscles": ["quads"], "limitations": "n = 12; one set of one exercise; the abstract gives neither the test load nor a separate p-value for traditional warm-up vs mobility only; no condition without any preparation.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "souza2024_warmup_load_squat", "title": "Effect of warm-up protocols using lower and higher loads on multiple-set back squat volume-load.", "authors": "Souza D et al.", "year": 2024, "journal": "PeerJ", "doi": "10.7717/peerj.17347", "pmid": "39006036", "url": "https://pubmed.ncbi.nlm.nih.gov/39006036/", "design": "acute_other", "outcome": "other", "population": "14 resistance-trained men; crossover of three back-squat warm-ups - 3 reps at 90% 1RM, 6 fast reps at 45% 1RM, or the usual 8 controlled reps at 45% 1RM - followed by multiple squat sets to failure", "finding": L("Total reps (p = 0.17) and total volume load (p = 0.15) over the sets did not differ between warm-ups. Only the first set showed a higher volume load after the heavy warm-up than after the usual one (p = 0.04). Changing the load of a single specific warm-up set therefore did not change multi-set squat performance.", "Общее число повторений (p = 0,17) и общий тоннаж (p = 0,15) за подходы между разминками не различались. Только в первом подходе тоннаж был выше после тяжёлой разминки, чем после обычной (p = 0,04). Таким образом, изменение веса одного специального разминочного подхода не изменило результат в приседе за несколько подходов."), "muscles": ["quads"], "limitations": "n = 14; one exercise; compares warm-up variants only (no condition without a warm-up); the abstract gives no rep counts.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "armes2020_predict_task_failure", "title": "\"Just One More Rep!\" - Ability to Predict Proximity to Task Failure in Resistance Trained Persons.", "authors": "Armes C et al.", "year": 2020, "journal": "Front Psychol", "doi": "10.3389/fpsyg.2020.565416", "pmid": "33424678", "url": "https://pubmed.ncbi.nlm.nih.gov/33424678/", "design": "acute_other", "outcome": "other", "population": "Adults with at least 1 year of resistance training; two experiments (n = 14 and n = 24) with knee-extension sets at 70% of 1RM or of the day's isometric maximum, stopped either at the self-determined repetition maximum or at true momentary failure", "finding": L("Participants stopped when they believed they could not complete another rep, yet on average could still perform about 2 more (meta-analytic estimate across both experiments 2.0, 95% CI 0.0 to 4.0).", "Участники останавливались, когда считали, что не смогут выполнить ещё одно повторение, но в среднем могли сделать ещё примерно 2 (метааналитическая оценка по обоим экспериментам 2,0, 95% ДИ от 0,0 до 4,0)."), "muscles": ["quads"], "limitations": "Small samples; knee extension only; wide confidence interval; deception design with single sets.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "hickmott2024_subjective_vs_velocity_rir", "title": "A Comparison of Subjective Estimations and Objective Velocities at Quantifying Proximity to Failure for the Bench Press in Resistance-Trained Men and Women.", "authors": "Hickmott LM et al.", "year": 2024, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000004784", "pmid": "38595310", "url": "https://pubmed.ncbi.nlm.nih.gov/38595310/", "design": "acute_other", "outcome": "other", "population": "36 resistance-trained adults (18 men, 18 women); bench-press sets to failure at 75-85% 1RM over several sessions, calling perceived 4 and 2 RIR, compared with RIR computed from an individual velocity profile", "finding": L("Velocity-derived RIR was more accurate than the lifters' own calls in the first two of three sets at 80% 1RM and at 75% and 80% (but not 85%) 1RM, at both 4 and 2 RIR. Subjective estimates were thus weakest in early sets and with lighter loads.", "RIR, рассчитанный по скорости, был точнее собственных оценок атлетов в первых двух из трёх подходов с 80% 1RM и при 75% и 80% (но не 85%) 1RM, и при 4, и при 2 RIR. Таким образом, субъективные оценки были слабее всего в ранних подходах и с более лёгкими весами."), "muscles": ["chest"], "limitations": "Bench press only; the abstract gives no error sizes in reps; the velocity method needs a device and an individual profile.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "holmes2026_rir_vs_rpe_accuracy", "title": "Accuracy of different methods for predicting proximity to failure during resistance training.", "authors": "Holmes G et al.", "year": 2026, "journal": "J Sports Sci", "doi": "10.1080/02640414.2026.2763157", "pmid": "43034269", "url": "https://pubmed.ncbi.nlm.nih.gov/43034269/", "design": "acute_other", "outcome": "other", "population": "32 adults (19 trained, 13 untrained); machine chest press and leg extension at 75% 1RM, calling 2 RIR in one session and Borg-RPE 8 in another and then continuing to momentary failure (randomised crossover)", "finding": L("Accuracy did not differ between the RIR and the RPE method (chest press difference -0.03 reps, 95% CI -0.50 to 0.44; leg extension 0.16 reps, 95% CI -0.39 to 0.71), and training status did not change this.", "Точность не различалась между методами RIR и RPE (жим от груди: разница −0,03 повторения, 95% ДИ от −0,50 до 0,44; разгибания ног: 0,16 повторения, 95% ДИ от −0,39 до 0,71), и тренированность этого не меняла."), "muscles": [], "limitations": "The abstract reports only the difference between methods, not the absolute error of either; two machine exercises; one load.", "confidence": "moderate", "verifiedOn": "2026-11-23"},
  {"id": "simao2005_order_upper_body", "title": "Influence of exercise order on the number of repetitions performed and perceived exertion during resistance exercises.", "authors": "Simão R et al.", "year": 2005, "journal": "J Strength Cond Res", "doi": "10.1519/1533-4287(2005)19<152:IOEOOT>2.0.CO;2", "pmid": "15705026", "url": "https://pubmed.ncbi.nlm.nih.gov/15705026/", "design": "acute_other", "outcome": "other", "population": "18 adults (14 men, 4 women) with at least 6 months of training; 3 sets to failure with 10RM loads on bench press, lat pulldown, shoulder press, biceps curl and triceps extension in that order and in reverse, 2 min rest", "finding": L("Whichever exercise was placed at the end of the sequence - large or small muscle group - yielded significantly fewer reps across its three sets, most clearly in the third set.", "Упражнение, поставленное в конец последовательности, — на большую или малую мышечную группу — давало значимо меньше повторений в трёх своих подходах, заметнее всего в третьем."), "muscles": [], "limitations": "The abstract gives no rep counts; upper body only; small sample; mixed muscle groups, so same-muscle and general fatigue cannot be separated.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "balsamo2013_order_adolescents", "title": "Exercise order influences number of repetitions and lactate levels but not perceived exertion during resistance exercise in adolescents.", "authors": "Balsamo S et al.", "year": 2013, "journal": "Res Sports Med", "doi": "10.1080/15438627.2013.825794", "pmid": "24067116", "url": "https://pubmed.ncbi.nlm.nih.gov/24067116/", "design": "acute_other", "outcome": "other", "population": "12 male adolescents (about 16 years); 3 sets with 10RM loads on triceps extension, biceps curl, bench press and seated row in that order and in reverse (crossover)", "finding": L("Total reps for an exercise were much lower when it came last instead of first: seated row 23.4 vs 13.6 and triceps extension 24.9 vs 16.3 (about 35-40% fewer). Exercises that only moved between second and third position changed less: bench press 14.3 vs 12.4 and biceps curl 16.2 vs 14.6 (about 10-13% fewer). RPE did not differ between orders.", "Общее число повторений в упражнении было намного ниже, когда оно шло последним, а не первым: тяга сидя — 23,4 против 13,6, разгибания на трицепс — 24,9 против 16,3 (примерно на 35–40% меньше). Упражнения, которые перемещались только между второй и третьей позицией, менялись меньше: жим лёжа — 14,3 против 12,4, сгибания на бицепс — 16,2 против 14,6 (примерно на 10–13% меньше). RPE между порядками не различалось."), "muscles": [], "limitations": "Adolescents; small sample; the rest interval is not stated in the abstract; the last exercise followed both a synergist and an unrelated exercise.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "perezcastilla2021_rtf_equations_pulls", "title": "Validity of Different Velocity-Based Methods and Repetitions-to-Failure Equations for Predicting the 1 Repetition Maximum During 2 Upper-Body Pulling Exercises.", "authors": "Pérez-Castilla A et al.", "year": 2021, "journal": "J Strength Cond Res", "doi": "10.1519/JSC.0000000000003076", "pmid": "30741875", "url": "https://pubmed.ncbi.nlm.nih.gov/30741875/", "design": "cross_sectional", "outcome": "strength", "population": "23 healthy adults (12 men, 11 women); lat pulldown and seated cable row: measured 1RM, then reps to failure at 80% 1RM", "finding": L("The Mayhew and Wathen reps-to-failure equations underestimated the measured 1RM by about 2 to 7 kg on both pulling exercises, whereas load-velocity methods showed no systematic bias (-1.75 to 1.65 kg). All estimates still correlated r ≥ 0.96 with the measured 1RM. The rep equations' absolute error exceeded that of the velocity methods on the seated row but not on the pulldown.", "Уравнения «повторения до отказа» Мэйхью и Уотена занижали измеренный 1RM примерно на 2–7 кг в обоих тяговых упражнениях, тогда как методы «вес — скорость» не показали систематического смещения (от −1,75 до 1,65 кг). Все оценки всё же коррелировали с измеренным 1RM с r ≥ 0,96. Абсолютная ошибка уравнений по повторениям превышала ошибку скоростных методов в тяге сидя, но не в тяге верхнего блока."), "muscles": ["lats", "upper_back"], "limitations": "Small sample; one load (80% 1RM); only two equations tested (not Epley).", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "garciaramos2019_rtf_equations_bench_pull", "title": "Reliability and validity of different methods of estimating the one-repetition maximum during the free-weight prone bench pull exercise.", "authors": "García-Ramos A et al.", "year": 2019, "journal": "J Sports Sci", "doi": "10.1080/02640414.2019.1626071", "pmid": "31164044", "url": "https://pubmed.ncbi.nlm.nih.gov/31164044/", "design": "cross_sectional", "outcome": "strength", "population": "26 trained men (22 rowers, 4 weightlifters); free-weight prone bench pull: incremental test to 1RM followed by a set to failure; 18 retested", "finding": L("The Lombardi and O'Connor reps-to-failure equations overestimated 1RM by 3.4-4.1%, while individual load-velocity profiles were unbiased (-0.4 to 0.9%). The Lombardi estimate was reliable between days (CV 3.4%), though less so than direct 1RM testing (CV 2.5%).", "Уравнения «повторения до отказа» Ломбарди и О'Коннора завышали 1RM на 3,4–4,1%, а индивидуальные профили «вес — скорость» были несмещёнными (от −0,4 до 0,9%). Оценка по Ломбарди была надёжной между днями (коэффициент вариации 3,4%), хотя и менее надёжной, чем прямой тест 1RM (2,5%)."), "muscles": ["lats", "upper_back"], "limitations": "One exercise; athletes; the abstract does not give the load or reps of the set to failure; Epley not tested.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "shimano2006_reps_percent_1rm_exercises", "title": "Relationship between the number of repetitions and selected percentages of one repetition maximum in free weight exercises in trained and untrained men.", "authors": "Shimano T et al.", "year": 2006, "journal": "J Strength Cond Res", "doi": "10.1519/R-18195.1", "pmid": "17194239", "url": "https://pubmed.ncbi.nlm.nih.gov/17194239/", "design": "acute_other", "outcome": "other", "population": "8 trained and 8 untrained men; one set to failure at 60, 80 and 90% 1RM in back squat, bench press and arm curl", "finding": L("At 60% 1RM clearly more reps were possible in the squat than in the bench press or arm curl; at 80% and 90% the differences between exercises were much smaller. Training status hardly mattered.", "При 60% 1RM в приседе было возможно явно больше повторений, чем в жиме лёжа или сгибаниях рук; при 80% и 90% различия между упражнениями были намного меньше. Тренированность почти не имела значения."), "muscles": [], "limitations": "n = 16; the abstract gives no rep counts; three exercises.", "confidence": "low", "verifiedOn": "2026-11-23"},
  {"id": "qin2025_percent1rm_rtf_vs_velocity", "title": "Gauging proximity to failure in the bench press: generalized velocity-based vs. %1RM-repetitions-to-failure approaches.", "authors": "Qin X et al.", "year": 2025, "journal": "BMC Sports Sci Med Rehabil", "doi": "10.1186/s13102-025-01098-2", "pmid": "40133968", "url": "https://pubmed.ncbi.nlm.nih.gov/40133968/", "design": "acute_other", "outcome": "other", "population": "19 men with at least 2 years of training; Smith-machine bench press sets to failure at 60% and 80% 1RM, with 2 and 4 RIR located by three generalised methods", "finding": L("A general %1RM-to-max-reps relationship missed the intended RIR by about 2.8-2.9 reps at 60% 1RM (the abstract calls this overestimating the intended RIR) but was accurate at 80% 1RM (errors -0.6 to 0.9 reps). A general RIR-velocity relationship was accurate at both loads, with a mean absolute error of 1.3 ± 0.7 reps.", "Общее соотношение «%1RM — максимум повторений» промахивалось мимо заданного RIR примерно на 2,8–2,9 повторения при 60% 1RM (в аннотации это названо завышением заданного RIR), но было точным при 80% 1RM (ошибки от −0,6 до 0,9 повторения). Общее соотношение «RIR — скорость» было точным при обоих весах, со средней абсолютной ошибкой 1,3 ± 0,7 повторения."), "muscles": ["chest"], "limitations": "n = 19 men; Smith-machine bench press only; two loads.", "confidence": "low", "verifiedOn": "2026-11-23"},
]);
